SELECT COUNT(*)
FROM social_account AS sa
WHERE sa.app_id = #{appId}
  AND sa.type = 'WX_MA'
  AND sa.del_flag = '0'

      AND sa.id != #{excludeId}

SELECT social_account.id, social_account.type, social_account.app_id, social_account.app_secret, social_account.create_time, social_account.update_time, social_account.del_flag, social_account.create_by, social_account.update_by, social_account.tenant_id FROM social_account AS social_account
AND social_account.del_flag = '0'
AND social_account.type = #{model.type}
AND social_account.app_id = #{model.appId}
